 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h = len(g)
    # Horizontal rails delimit independent bands.
    rails = [r for r, row in enumerate(g) if len(set(row)) == 1 and row[0] != 0]
    start, bands = 0, []
    for r in rails:
        if start < r:
            bands.append((start, r))
        start = r + 1
    if start < h:
        bands.append((start, h))
    # Vertical divider columns. The demo layout has three active panels, each
    # five cells wide, separated by a 1-cell rail and a 2-cell gap.
    w = len(g[0])
    vr = [c for c in range(w) if len({g[r][c] for r in range(h)}) == 1 and g[0][c] != 0]
    start, panels = 0, []
    for c in vr:
        if start < c:
            panels.append((start, c))
        start = c + 1
    if start < w:
        panels.append((start, w))
    if len(panels) < 3:
        return g
    for r0, r1 in bands:
        A = [[grid[r][c] for c in range(panels[0][0], panels[0][1])] for r in range(r0, r1)]
        B = [[grid[r][c] for c in range(panels[1][0], panels[1][1])] for r in range(r0, r1)]
        if len(A[0]) != len(B[0]):
            continue
        hasA = any(v != 0 for row in A for v in row)
        hasB = any(v != 0 for row in B for v in row)
        if hasA and not hasB:
            source, target = A, panels[1][0]
            for rr, row in enumerate(source):
                for cc, value in enumerate(reversed(row)):
                    g[r0 + rr][target + cc] = value
        elif hasA and hasB:
            # In the demos, the first two panels are intended to form a mirror
            # pair, even if the existing second pattern is not complete.
            source, target = A, panels[1][0]
            for rr, row in enumerate(source):
                for cc, value in enumerate(reversed(row)):
                    g[r0 + rr][target + cc] = value
    return g

