    """Reflect isolated motif cells across the internal 8-colored panel rails."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Rail coordinates in the demonstrations are columns 4, 9, 14 and rows
    # containing uninterrupted rail color. Work in each connected panel area.
