    horizontal_rails = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != 0]
    def intervals(n, rails):
        res, a = [], 0
        for p in rails:
            if a < p: res.append((a, p))
            a = p + 1
        if a < n: res.append((a, n))
        return res
    cols = intervals(w, vertical_rails)
    rows = intervals(h, horizontal_rails)
    original = [row[:] for row in grid]
    for r0, r1 in rows:
        for j in range(len(cols)-1):
            a0,a1=cols[j]; b0,b1=cols[j+1]
            if a1-a0 != b1-b0: continue
            for r in range(r0,r1):
                for k in range(a1-a0):
                    left=original[r][a0+k]
                    right=original[r][b0+(a1-a0-1-k)]
                    # Reflect non-background marks from the panel containing a
