 "content": "def transform(grid):
    """Complete panel motifs by horizontal reflection within each band."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    rails = [c for c in range(w) if all(grid[r][c] == grid[0][c] and grid[0][c] != 0 for r in range(h))]
    hrails = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != 0]

    def intervals(n, cuts):
        result, start = [], 0
        for cut in cuts:
            if start < cut:
                result.append((start, cut))
            start = cut + 1
        if start < n:
            result.append((start, n))
        return result

    cols, rows = intervals(w, rails), intervals(h, hrails)
    # Only colors used as foreground motif colors participate; rail colors and
    # zero background are never copied. Demos show each motif is mirrored into
    # its immediate neighboring empty panel, while already-present motifs stay.
    rail_colors = {grid[r][c] for r in range(h) for c in rails}
    foreground = {v for row in grid for v in row if v != 0 and v not in rail_colors}
    for r0, r1 in rows:
        original = [row[:] for row in grid]
        for color in foreground:
            masks = []
            for c0, c1 in cols:
                masks.append([[original[r][c] == color for c in range(c0, c1)] for r in range(r0, r1)])
            has = [any(any(row) for row in mask) for mask in masks]
            for i in range(len(cols)-1):
                if has[i] and not has[i+1] and cols[i][1]-cols[i][0] == cols[i+1][1]-cols[i+1][0]:
                    c0 = cols[i+1][0]
                    for rr, row in enumerate(masks[i]):
                        for cc, val in enumerate(reversed(row)):
                            if val:
                                out[r0+rr][c0+cc] = color
                elif has[i+1] and not has[i] and cols[i][1]-cols[i][0] == cols[i+1][1]-cols[i+1][0]:
                    c0 = cols[i][0]
                    for rr, row in enumerate(masks[i+1]):
                        for cc, val in enumerate(reversed(row)):
                            if val:
                                out[r0+rr][c0+cc] = color
    return out

