 "content": "def transform(grid):
    """Complete a motif as the horizontal reflection of its adjacent pattern."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Divider rails are full-height/full-width constant non-background lines.
    row_rails = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != 0]
    col_rails = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != 0]

    def segments(size, rails):
        ans, start = [], 0
        for x in rails:
            if start < x:
                ans.append((start, x))
            start = x + 1
        if start < size:
            ans.append((start, size))
        return ans

    bands = segments(h, row_rails)
    panels = segments(w, col_rails)
    for top, bottom in bands:
        # The demos establish that panel 0 and panel 1 form the relevant pair;
        # completion copies the motif's mirror while retaining its color.
        if len(panels) < 2:
            continue
        a0, a1 = panels[0]
        b0, b1 = panels[1]
        if a1-a0 != b1-b0:
            continue
        left = [[grid[r][c] for c in range(a0, a1)] for r in range(top, bottom)]
        right = [[grid[r][c] for c in range(b0, b1)] for r in range(top, bottom)]
        la = any(v != 0 for row in left for v in row)
        rb = any(v != 0 for row in right for v in row)
        # A blank member receives the reflection of its occupied neighbor.
        # If both have content, the lower three-row demo's partial motif is
        # completed from the left-side pattern into the right member.
        if la and (not rb or any(v != 0 for row in right for v in row)):
            for rr, row in enumerate(left):
                for cc, value in enumerate(reversed(row)):
                    out[top+rr][b0+cc] = value
        elif rb and not la:
            for rr, row in enumerate(right):
                for cc, value in enumerate(reversed(row)):
                    out[top+rr][a0+cc] = value
    return out

