 "content": "def transform(grid):
    """Complete each incomplete motif by mirroring its matching pattern."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    row_rails = [r for r, row in enumerate(grid) if len(set(row)) == 1 and row[0] != 0]
    col_rails = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != 0]

    def bands(n, rails):
        ans, start = [], 0
        for q in rails:
            if start < q:
                ans.append((start, q))
            start = q + 1
        if start < n:
            ans.append((start, n))
        return ans

    row_bands = bands(h, row_rails)
    col_panels = bands(w, col_rails)
    for top, bottom in row_bands:
        for i in range(len(col_panels) - 1):
            a0, a1 = col_panels[i]
            b0, b1 = col_panels[i + 1]
            if a1 - a0 != b1 - b0:
                continue
            A = [[grid[r][c] for c in range(a0, a1)] for r in range(top, bottom)]
            B = [[grid[r][c] for c in range(b0, b1)] for r in range(top, bottom)]
            # Add only foreground cells where the reflected counterpart is absent.
            # Existing foreground on both sides is preserved as supplied.
            width = a1 - a0
            for rr in range(bottom - top):
                for cc in range(width):
                    av = A[rr][cc]
                    bv = B[rr][width - 1 - cc]
                    if av != 0 and bv == 0:
                        out[top + rr][b0 + width - 1 - cc] = av
                    elif bv != 0 and av == 0:
                        out[top + rr][a0 + cc] = bv
    return out

